            return;
        }
        if (!isOpen) {
            reference(null);
            return;
        }
        if (anchorReference.mode === 'element') {
            reference(anchorReference.value || null);
            return;
        }
        if (anchorReference.mode === 'position') {
            if (!anchorReference.value) {
                reference(null);
